--
-- Name: fn_atualizar_valor_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_atualizar_valor_total() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    v_pedido_id bigint;
begin
    if tg_op = 'DELETE' then
        v_pedido_id := old.pedido_id;
    else
        v_pedido_id := new.pedido_id;
    end if;

    update pedido
    set valor_total = (
        select coalesce(sum(quantidade * preco_unitario), 0)
        from itens_pedido
        where pedido_id = v_pedido_id
    )
    where id_pedido = v_pedido_id;

    return null;
end;
$$;


--
-- Name: fn_controlar_estoque(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_controlar_estoque() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    v_nome varchar;
    v_estoque int;
begin
    if tg_op in ('UPDATE', 'DELETE') then
        update produto
        set estoque = estoque + old.quantidade
        where id_produto = old.produto_id;
    end if;

    if tg_op = 'DELETE' then
        return old;
    end if;

    select nome, estoque into v_nome, v_estoque
    from produto
    where id_produto = new.produto_id
    for update;

    if v_estoque < new.quantidade then
        raise exception 'estoque insuficiente de %: disponível %, pedido %.', v_nome, v_estoque, new.quantidade;
    end if;

    update produto
    set estoque = estoque - new.quantidade
    where id_produto = new.produto_id;

    return new;
end;
$$;


--
-- Name: fn_produtos_mais_vendidos(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_produtos_mais_vendidos(p_limite integer) RETURNS TABLE(produto character varying, quantidade_vendida bigint, faturamento numeric)
    LANGUAGE plpgsql
    AS $$
begin
    return query
    select p.nome, sum(i.quantidade)::bigint, sum(i.quantidade * i.preco_unitario)
    from itens_pedido i
    join produto p on p.id_produto = i.produto_id
    group by p.id_produto, p.nome
    order by 2 desc
    limit p_limite;
end;
$$;


--
-- Name: fn_resumo_cliente(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_resumo_cliente(p_cpf character varying) RETURNS TABLE(nome_cliente character varying, total_pedidos bigint, total_gasto numeric, ultimo_pedido timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
begin
    return query
    select c.nome, count(p.id_pedido), coalesce(sum(p.valor_total), 0), max(p.data_hora)::timestamp
    from cliente c
    left join pedido p on p.cliente_id = c.id_cliente
    where c.cpf = p_cpf
    group by c.id_cliente, c.nome;
end;
$$;


--
-- Name: sp_registrar_venda(character varying, character varying, bigint[], integer[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_registrar_venda(IN p_cpf character varying, IN p_forma_pagamento character varying, IN p_produtos bigint[], IN p_quantidades integer[])
    LANGUAGE plpgsql
    AS $$
declare
    v_cliente_id bigint;
    v_pedido_id bigint;
    v_preco numeric(10,2);
    v_total_itens int;
    i int;
begin
    v_total_itens := coalesce(array_length(p_produtos, 1), 0);

    if v_total_itens = 0 then
        raise exception 'informe pelo menos um produto.';
    end if;

    if v_total_itens <> coalesce(array_length(p_quantidades, 1), 0) then
        raise exception 'informe uma quantidade para cada produto.';
    end if;

    if p_cpf is not null then
        select id_cliente into v_cliente_id from cliente where cpf = p_cpf;

        if v_cliente_id is null then
            raise exception 'cliente com cpf % não foi encontrado.', p_cpf;
        end if;
    end if;

    values (v_cliente_id, p_forma_pagamento)
    returning id_pedido into v_pedido_id;

    for i in 1..v_total_itens loop
        if p_quantidades[i] <= 0 then
            raise exception 'a quantidade deve ser maior que zero.';
        end if;

        select preco_unitario into v_preco from produto where id_produto = p_produtos[i];

        if v_preco is null then
            raise exception 'produto % não foi encontrado.', p_produtos[i];
        end if;

        values (v_pedido_id, p_produtos[i], p_quantidades[i], v_preco);
    end loop;
end;
$$;


--
-- Name: sp_repor_estoque(bigint, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_repor_estoque(IN p_produto_id bigint, IN p_quantidade integer)
    LANGUAGE plpgsql
    AS $$
begin
    if p_quantidade <= 0 then
        raise exception 'a quantidade deve ser maior que zero.';
    end if;

    update produto
    set estoque = estoque + p_quantidade
    where id_produto = p_produto_id;

    if not found then
        raise exception 'produto % não foi encontrado.', p_produto_id;
    end if;
end;
$$;


